"""Generate the architecture view from module docstrings and internal imports."""

from __future__ import annotations

import ast
from pathlib import Path

# The generated file name (CI drift-check object).
ARCHITECTURE_FILENAME = "ARCHITECTURE.md"

_HEADING = "# Spec architecture"


def iter_py_files(*, package_root: Path) -> list[Path]:
    """package_root All.py ( sorted, skip __pycache__)."""
    return sorted(path for path in package_root.rglob("*.py") if "__pycache__" not in path.parts)


def module_name(*, path: Path, top_parent: Path) -> str:
    """File path  → point the module name (relative to top_parent), __init__ is returned to the package."""
    parts = list(path.relative_to(top_parent).with_suffix("").parts)
    if parts and parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)


def build_graph(*, package_root: Path) -> tuple[dict[str, Path], list[tuple[str, str]]]:
    """Construct: Returns (module name file path, side list [(src_module, dst_module)]).

    ”Only between the files of the project.” import; pointing to standard libraries/Third parties/No module neglects.
    """
    top_parent = package_root.parent
    nodes: dict[str, Path] = {}
    for path in iter_py_files(package_root=package_root):
        nodes[module_name(path=path, top_parent=top_parent)] = path

    edges: set[tuple[str, str]] = set()
    for src_module, path in nodes.items():
        for target in _imported_modules(path=path, src_module=src_module):
            dst = _resolve_to_node(target=target, nodes=nodes)
            if dst is not None and dst != src_module:
                edges.add((src_module, dst))
    return nodes, sorted(edges)


def missing_docstrings(*, package_root: Path) -> list[str]:
    """Returns the file path (file + package __init__) that is missing. A comment is made for hard verification."""
    missing: list[str] = []
    for path in iter_py_files(package_root=package_root):
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        if not (ast.get_docstring(tree) or "").strip():
            missing.append(str(path))
    return missing


def render_architecture(*, package_root: Path) -> str:
    """Renders the full text of ARCHITECTURE.md (pure functions, Zirconium equivalent): The subsystem Zirconium Zirt Zirt Zirt Qirt Qrz relationship map."""
    nodes, edges = build_graph(package_root=package_root)
    top_parent = package_root.parent

    blocks = [
        _HEADING,
        f"> Generated by `spec graph` from the code and docstrings under `{package_root}/`. Do not edit by hand.",
        _render_subsystems(package_root=package_root, top_parent=top_parent),
        _render_relation_graph(nodes=nodes, edges=edges),
    ]
    return "\n\n".join(blocks).rstrip("\n") + "\n"


def write_architecture(*, specs_root: Path, package_root: Path) -> Path:
    """Ender + Crash specs_root/ARCHITECTURE.md, return path."""
    path = specs_root / ARCHITECTURE_FILENAME
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render_architecture(package_root=package_root), encoding="utf-8")
    return path


def _render_subsystems(*, package_root: Path, top_parent: Path) -> str:
    """Each package (with __init__) = a subsystem segment: module level docstring + file level for each file docstring."""
    lines = ["## Subsystems and components"]
    # Package directory (with __init__.py), sorted by path.
    packages = sorted({path.parent for path in iter_py_files(package_root=package_root)})
    for pkg_dir in packages:
        pkg_name = module_name(path=pkg_dir / "__init__.py", top_parent=top_parent) or "(root)"
        init_path = pkg_dir / "__init__.py"
        pkg_doc = _first_line(path=init_path) if init_path.is_file() else ""
        lines.append("")
        lines.append(f"### {pkg_name}")
        lines.append("")
        lines.append(f"_{pkg_doc or '(missing package docstring)'}_")
        lines.append("")
        lines.append("| Component | Responsibility (first line of the module docstring) |")
        lines.append("|----|----|")
        files = sorted(
            path
            for path in package_root.rglob("*.py")
            if path.parent == pkg_dir and "__pycache__" not in path.parts
        )
        for path in files:
            doc = _first_line(path=path) or "(missing module docstring)"
            lines.append(f"| `{path.name}` | {_cell(doc)} |")
    return "\n".join(lines)


def _render_relation_graph(*, nodes: dict[str, Path], edges: list[tuple[str, str]]) -> str:
    """Indices of relationships (Mermaid): Node = module short name, side = import."""
    lines = ["## Import graph", "", "```mermaid", "graph LR"]
    for module in sorted(nodes):
        lines.append(f'    {_node(module)}["{_short(module)}"]')
    for src, dst in edges:
        lines.append(f"    {_node(src)} --> {_node(dst)}")
    lines.append("```")
    return "\n".join(lines)


def _imported_modules(*, path: Path, src_module: str) -> list[str]:
    """The name of the import target module in the parsing file (with relative import resolution as absolute)."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except SyntaxError:
        return []
    # The relative Import '.' is based on the package** in **: the package for the normal module a.b.c is a.b; the package __init__ is its own.
    is_package = path.name == "__init__.py"
    src_package = src_module if is_package else src_module.rpartition(".")[0]
    targets: list[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            targets.extend(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            base = _absolute_from(module=node.module, level=node.level, src_package=src_package)
            if base is None:
                continue
            # From base effect X  →  candidate base.X (submodule) and base itself.
            for alias in node.names:
                targets.append(f"{base}.{alias.name}" if base else alias.name)
            if base:
                targets.append(base)
    return targets


def _absolute_from(*, module: str | None, level: int, src_package: str) -> str | None:
    """Resolves the relative module of `from . / .. import` as absolute naming.

    src_package is the package where the Import is located (the normal module takes its parent ’s, the __init__ takes its own).
    *Live=1 means src_package itself; *Live=2 means the upper layer; and so on.
    """
    if level == 0:
        return module
    parts = src_package.split(".") if src_package else []
    cut = len(parts) - (level - 1)
    base = parts[:cut] if cut >= 0 else []
    if module:
        base = [*base, *module.split(".")]
    return ".".join(base) if base else None


def _resolve_to_node(*, target: str, nodes: dict[str, Path]) -> str | None:
    """The Import target is parsed to a known node: an exact hit or is returned to its maximum known prefix (package)."""
    if target in nodes:
        return target
    parts = target.split(".")
    for cut in range(len(parts) - 1, 0, -1):
        candidate = ".".join(parts[:cut])
        if candidate in nodes:
            return candidate
    return None


def _first_line(*, path: Path) -> str:
    """The first line of the document docstring (leave); no empty string."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except (SyntaxError, OSError):
        return ""
    doc = (ast.get_docstring(tree) or "").strip()
    return doc.split("\n", 1)[0].strip() if doc else ""


def _node(module: str) -> str:
    """The module name is a valid Mermaid node name."""
    return "n" + "".join(ch if ch.isalnum() else "_" for ch in module)


def _short(module: str) -> str:
    """Node label: Delete the last two paragraphs and omit the long prefix."""
    return ".".join(module.split(".")[-2:])


def _cell(text: str) -> str:
    """Table unit: Single-line, transposition vertical lines."""
    return text.replace("\n", " ").replace("|", "\\|")
